create table if not exists board_events (id uuid primary key default gen_random_uuid(), room_id uuid references classroom_rooms(id) on delete cascade, event_id text not null, actor_user_id uuid, event_type text not null, sequence_number int not null default 0, payload_json jsonb not null default '{}'::jsonb, created_at timestamptz default now(), unique(room_id,event_id)); alter table board_events enable row level security; create index if not exists idx_board_events_room_sequence on board_events(room_id,sequence_number); alter publication supabase_realtime add table board_events;
